selector_to_html = {"a[href=\"#unirunner-configuration\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">UniRunner Configuration<a class=\"headerlink\" href=\"#unirunner-configuration\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#ucx-network\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">UCX Network<a class=\"headerlink\" href=\"#ucx-network\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#tuner-configuration\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Tuner Configuration<a class=\"headerlink\" href=\"#tuner-configuration\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#hybridrunner-configuration\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">HybridRunner Configuration<a class=\"headerlink\" href=\"#hybridrunner-configuration\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#flagcx-environment-variables\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagCX Environment Variables<a class=\"headerlink\" href=\"#flagcx-environment-variables\" title=\"Link to this heading\">#</a></h1><p>This document provides a comprehensive reference for all environment variables used in FlagCX.</p>", "a[href=\"#table-of-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Table of Contents<a class=\"headerlink\" href=\"#table-of-contents\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#accl-barex-transport\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">ACCL/Barex transport<a class=\"headerlink\" href=\"#accl-barex-transport\" title=\"Link to this heading\">#</a></h3><p>Environment variables change runtime behavior without rebuilding the library. The following settings apply only to deployments that build and use the ACCL/Barex transport adaptor:</p>", "a[href=\"#debug-and-logging\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Debug and Logging<a class=\"headerlink\" href=\"#debug-and-logging\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#proxy-and-runtime\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Proxy and Runtime<a class=\"headerlink\" href=\"#proxy-and-runtime\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#communication-mode\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Communication Mode<a class=\"headerlink\" href=\"#communication-mode\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#miscellaneous\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Miscellaneous<a class=\"headerlink\" href=\"#miscellaneous\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#socket-network\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Socket Network<a class=\"headerlink\" href=\"#socket-network\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#gloo-network\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Gloo Network<a class=\"headerlink\" href=\"#gloo-network\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#accl-barex-and-ppu-integration\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">ACCL/Barex and PPU Integration<a class=\"headerlink\" href=\"#accl-barex-and-ppu-integration\" title=\"Link to this heading\">#</a></h3><p>Build the ACCL/Barex network adaptor with <code class=\"docutils literal notranslate\"><span class=\"pre\">USE_ACCL_BAREX=1</span></code>. The PPU integration commonly uses <code class=\"docutils literal notranslate\"><span class=\"pre\">USE_PPU=1</span> <span class=\"pre\">USE_ACCL_BAREX=1</span></code>; integration environments may also select <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGCX_P2P_TRANSPORT=accl</span></code>, enable <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGCX_MEM_ENABLE=1</span></code>, and disable virtual memory with <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGCX_VMM_ENABLE=0</span></code>. These settings are integration prerequisites, not universal defaults.</p>", "a[href=\"#ib-retransmission\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">IB Retransmission<a class=\"headerlink\" href=\"#ib-retransmission\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#buffer-and-memory\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Buffer and Memory<a class=\"headerlink\" href=\"#buffer-and-memory\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#infiniband-ib-settings\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">InfiniBand (IB) Settings<a class=\"headerlink\" href=\"#infiniband-ib-settings\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#network-configuration\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Network Configuration<a class=\"headerlink\" href=\"#network-configuration\" title=\"Link to this heading\">#</a></h2><h3>InfiniBand (IB) Settings<a class=\"headerlink\" href=\"#infiniband-ib-settings\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#topology-configuration\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Topology Configuration<a class=\"headerlink\" href=\"#topology-configuration\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#p2p-engine-configuration\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">P2P Engine Configuration<a class=\"headerlink\" href=\"#p2p-engine-configuration\" title=\"Link to this heading\">#</a></h2><p><strong>Note</strong>: These variables configure the FlagCX P2P Engine for one-sided RDMA operations, primarily used when integrating with transfer frameworks like NIXL.</p>", "a[href=\"#notes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Notes<a class=\"headerlink\" href=\"#notes\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#plugin-configuration\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Plugin Configuration<a class=\"headerlink\" href=\"#plugin-configuration\" title=\"Link to this heading\">#</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
